import asyncio
import time
from contextlib import contextmanager
from types import SimpleNamespace
from typing import Any, Iterator, cast
from unittest.mock import MagicMock, call

import pytest
from mcp.shared.auth import OAuthClientInformationFull, OAuthMetadata, OAuthToken
from pydantic import AnyHttpUrl

from onyx.db.enums import MCPOAuthProviderMode, MCPTransport
from onyx.db.models import MCPServer
from onyx.error_handling.exceptions import OnyxError
from onyx.server.features.mcp import oauth
from onyx.server.features.mcp.models import MCPOAuthKeys

_REDIRECT_URI = "https://onyx.example.com/mcp/oauth/callback"
_DISCOVERED_METADATA = OAuthMetadata(
    issuer=cast(AnyHttpUrl, "https://idp.other-host.com"),
    authorization_endpoint=cast(AnyHttpUrl, "https://idp.other-host.com/authorize"),
    token_endpoint=cast(AnyHttpUrl, "https://idp.other-host.com/token"),
)


def _client_information(client_id: str = "client-id") -> OAuthClientInformationFull:
    return OAuthClientInformationFull(
        client_id=client_id,
        client_secret=f"{client_id}-secret",
        redirect_uris=[_REDIRECT_URI],
        token_endpoint_auth_method="client_secret_post",
    )


def _server(provider_mode: MCPOAuthProviderMode) -> MCPServer:
    known_provider = provider_mode is MCPOAuthProviderMode.KNOWN_PROVIDER
    return cast(
        MCPServer,
        SimpleNamespace(
            id=42,
            name="Protected MCP",
            server_url="https://mcp.example.com/mcp",
            transport=MCPTransport.STREAMABLE_HTTP,
            oauth_provider_mode=provider_mode,
            oauth_authorization_endpoint=(
                "https://accounts.example.com/authorize" if known_provider else None
            ),
            oauth_token_endpoint=(
                "https://accounts.example.com/token" if known_provider else None
            ),
        ),
    )


def _provider(
    provider_mode: MCPOAuthProviderMode,
    *,
    load_stored_tokens: bool = True,
) -> oauth.OnyxOAuthClientProvider:
    return oauth.make_oauth_provider(
        _server(provider_mode),
        connection_config_id=101,
        shared_client_config_id=None,
        load_stored_tokens=load_stored_tokens,
    )


def _patch_config_read(
    monkeypatch: pytest.MonkeyPatch,
    config_data: dict[str, Any],
) -> None:
    @contextmanager
    def fake_session() -> Iterator[object]:
        yield object()

    monkeypatch.setattr(oauth, "get_session_with_current_tenant", fake_session)
    monkeypatch.setattr(
        oauth,
        "get_connection_config_by_id",
        lambda *_args, **_kwargs: SimpleNamespace(id=101),
    )
    monkeypatch.setattr(oauth, "extract_connection_data", lambda _config: config_data)


def test_authorization_result_does_not_inherit_previous_grants_refresh_token(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    registration = _client_information("same-client")
    config_data: dict[str, Any] = {
        MCPOAuthKeys.CLIENT_INFO.value: registration.model_dump(mode="json"),
        MCPOAuthKeys.TOKENS.value: {
            "access_token": "existing-access-token",
            "refresh_token": "existing-refresh-token",
            "token_type": "Bearer",
        },
    }
    _patch_config_read(monkeypatch, config_data)
    get_config = MagicMock(return_value=SimpleNamespace(id=101))
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "get_connection_config_by_id", get_config)
    monkeypatch.setattr(oauth, "update_connection_config", update_config)
    asyncio.run(
        oauth.OnyxTokenStorage(101).set_authorization_result(
            OAuthToken(access_token="new-access-token", token_type="Bearer"),
            registration,
        )
    )

    assert get_config.call_args.kwargs["for_update"] is True
    persisted = update_config.call_args.args[2]
    assert persisted[MCPOAuthKeys.CLIENT_INFO.value] == (
        registration.model_dump(mode="json")
    )
    assert persisted[MCPOAuthKeys.TOKENS.value]["refresh_token"] is None


def test_authorization_result_rejects_a_replaced_client_registration(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config_data: dict[str, Any] = {
        MCPOAuthKeys.CLIENT_INFO.value: _client_information(
            "replacement-client"
        ).model_dump(mode="json"),
    }
    _patch_config_read(monkeypatch, config_data)
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "update_connection_config", update_config)

    with pytest.raises(OnyxError, match="client registration changed"):
        asyncio.run(
            oauth.OnyxTokenStorage(
                101,
                expected_client_information_fingerprint=(
                    oauth.mcp_oauth_client_information_fingerprint(
                        _client_information("original-client")
                    )
                ),
            ).set_authorization_result(
                OAuthToken(access_token="new-access-token", token_type="Bearer"),
                _client_information("original-client"),
            )
        )

    update_config.assert_not_called()


def test_refresh_write_is_skipped_after_a_new_grant_wins(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    config_data: dict[str, Any] = {
        MCPOAuthKeys.TOKENS.value: {
            "access_token": "new-grant-access-token",
            "refresh_token": "new-grant-refresh-token",
            "token_type": "Bearer",
        }
    }
    _patch_config_read(monkeypatch, config_data)
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "update_connection_config", update_config)

    persisted = asyncio.run(
        oauth.OnyxTokenStorage(101).set_refreshed_tokens(
            OAuthToken(
                access_token="late-refresh-access-token",
                refresh_token="rotated-refresh-token",
                token_type="Bearer",
            ),
            redeemed_refresh_token="old-refresh-token",
        )
    )

    assert persisted is False
    update_config.assert_not_called()


def test_authorization_result_rejects_changed_routing_headers_at_write_time(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    registration = _client_information()
    config_data: dict[str, Any] = {
        "headers": {"X-Gateway-Tenant": "replacement-tenant"},
        MCPOAuthKeys.CLIENT_INFO.value: registration.model_dump(mode="json"),
    }
    _patch_config_read(monkeypatch, config_data)
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "update_connection_config", update_config)

    with pytest.raises(OnyxError, match="connection headers changed"):
        asyncio.run(
            oauth.OnyxTokenStorage(
                101,
                expected_connection_headers_fingerprint=(
                    oauth.mcp_oauth_connection_headers_fingerprint(
                        {"X-Gateway-Tenant": "original-tenant"}
                    )
                ),
            ).set_authorization_result(
                OAuthToken(access_token="new-access-token", token_type="Bearer"),
                registration,
            )
        )

    update_config.assert_not_called()


def test_client_fingerprint_is_stable_for_nested_object_key_order() -> None:
    first = _client_information().model_copy(
        update={"jwks": {"keys": [{"kid": "one", "kty": "RSA"}], "version": 1}}
    )
    second = _client_information().model_copy(
        update={"jwks": {"version": 1, "keys": [{"kty": "RSA", "kid": "one"}]}}
    )

    assert oauth.mcp_oauth_client_information_fingerprint(first) == (
        oauth.mcp_oauth_client_information_fingerprint(second)
    )


def test_shared_client_lookup_does_not_write_stale_user_configuration(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    user_config = SimpleNamespace(id=101)
    shared_config = SimpleNamespace(id=100)
    registration = _client_information("shared-registration")
    config_data_by_id = {
        101: {"headers": {"X-Gateway-Tenant": "tenant-1"}},
        100: {MCPOAuthKeys.CLIENT_INFO.value: registration.model_dump(mode="json")},
    }

    @contextmanager
    def fake_session() -> Iterator[object]:
        yield object()

    monkeypatch.setattr(oauth, "get_session_with_current_tenant", fake_session)
    monkeypatch.setattr(
        oauth,
        "get_connection_config_by_id",
        lambda config_id, *_args, **_kwargs: (
            user_config if config_id == 101 else shared_config
        ),
    )
    monkeypatch.setattr(
        oauth,
        "extract_connection_data",
        lambda config: config_data_by_id[config.id],
    )
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "update_connection_config", update_config)
    storage = oauth.OnyxTokenStorage(101, shared_client_config_id=100)

    assert asyncio.run(storage.get_client_info()) == registration
    update_config.assert_not_called()


def test_client_registration_isolated_to_each_locked_configuration_row(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    session = MagicMock()
    configs = {101: SimpleNamespace(id=101), 100: SimpleNamespace(id=100)}
    config_data = {
        101: {
            MCPOAuthKeys.TOKENS.value: {"access_token": "user-token"},
            "headers": {"Authorization": "Bearer user-token"},
        },
        100: {"unrelated": "preserved"},
    }

    @contextmanager
    def fake_session() -> Iterator[object]:
        yield session

    get_config = MagicMock(
        side_effect=lambda config_id, *_args, **_kwargs: configs[config_id]
    )
    monkeypatch.setattr(oauth, "get_session_with_current_tenant", fake_session)
    monkeypatch.setattr(oauth, "get_connection_config_by_id", get_config)
    monkeypatch.setattr(
        oauth, "extract_connection_data", lambda config: config_data[config.id]
    )
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "update_connection_config__no_commit", update_config)
    storage = oauth.OnyxTokenStorage(101, shared_client_config_id=100)
    registration = _client_information("new-registration")

    asyncio.run(storage.set_client_info(registration))

    assert get_config.call_args_list == [
        call(100, session, for_update=True),
        call(101, session, for_update=True),
    ]
    expected_registration = registration.model_dump(mode="json")
    assert config_data[101][MCPOAuthKeys.CLIENT_INFO.value] == expected_registration
    assert config_data[100] == {
        "unrelated": "preserved",
        MCPOAuthKeys.CLIENT_INFO.value: expected_registration,
    }
    assert update_config.call_count == 2
    session.commit.assert_called_once_with()


def test_concurrent_registration_adopts_the_shared_winner_before_retry(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    session = MagicMock()
    configs = {101: SimpleNamespace(id=101), 100: SimpleNamespace(id=100)}
    winner = _client_information("winning-registration")
    config_data = {
        101: {"headers": {"X-Gateway-Tenant": "tenant-1"}},
        100: {
            MCPOAuthKeys.CLIENT_INFO.value: winner.model_dump(mode="json"),
        },
    }

    @contextmanager
    def fake_session() -> Iterator[MagicMock]:
        yield session

    monkeypatch.setattr(oauth, "get_session_with_current_tenant", fake_session)
    monkeypatch.setattr(
        oauth,
        "get_connection_config_by_id",
        lambda config_id, *_args, **_kwargs: configs[config_id],
    )
    monkeypatch.setattr(
        oauth, "extract_connection_data", lambda config: config_data[config.id]
    )
    update_config = MagicMock()
    monkeypatch.setattr(oauth, "update_connection_config__no_commit", update_config)

    with pytest.raises(oauth.MCPClientRegistrationConflict):
        asyncio.run(
            oauth.OnyxTokenStorage(101, shared_client_config_id=100).set_client_info(
                _client_information("losing-registration")
            )
        )

    assert config_data[101][MCPOAuthKeys.CLIENT_INFO.value] == (
        winner.model_dump(mode="json")
    )
    assert config_data[100][MCPOAuthKeys.CLIENT_INFO.value] == (
        winner.model_dump(mode="json")
    )
    session.commit.assert_called_once_with()


def test_token_load_hydrates_expiry_used_by_the_sdk(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    provider = _provider(MCPOAuthProviderMode.KNOWN_PROVIDER)
    expired_at = time.time() - 60
    _patch_config_read(
        monkeypatch,
        {
            MCPOAuthKeys.TOKEN_EXPIRES_AT.value: expired_at,
            MCPOAuthKeys.TOKENS.value: {
                "access_token": "expired-token",
                "token_type": "Bearer",
            },
        },
    )

    tokens = asyncio.run(provider.context.storage.get_tokens())
    provider.context.current_tokens = tokens

    assert provider.context.token_expiry_time == expired_at
    assert provider.context.is_token_valid() is False


def test_reauthentication_ignores_tokens_but_rehydrates_metadata(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    provider = _provider(
        MCPOAuthProviderMode.AUTO_DISCOVERY,
        load_stored_tokens=False,
    )
    _patch_config_read(
        monkeypatch,
        {
            MCPOAuthKeys.TOKENS.value: {
                "access_token": "current-token",
                "token_type": "Bearer",
            },
            MCPOAuthKeys.METADATA.value: _DISCOVERED_METADATA.model_dump(mode="json"),
        },
    )

    assert asyncio.run(provider.context.storage.get_tokens()) is None
    assert provider.context.oauth_metadata == _DISCOVERED_METADATA


def test_token_load_clears_stale_expiry_when_storage_has_none(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    provider = _provider(MCPOAuthProviderMode.AUTO_DISCOVERY)
    provider.context.token_expiry_time = 999.0
    _patch_config_read(
        monkeypatch,
        {
            MCPOAuthKeys.TOKENS.value: {
                "access_token": "current-token",
                "token_type": "Bearer",
            }
        },
    )

    asyncio.run(provider.context.storage.get_tokens())

    assert provider.context.token_expiry_time is None


def test_token_load_does_not_override_known_provider_metadata(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    provider = _provider(MCPOAuthProviderMode.KNOWN_PROVIDER)
    _patch_config_read(
        monkeypatch,
        {
            MCPOAuthKeys.METADATA.value: _DISCOVERED_METADATA.model_dump(mode="json"),
            MCPOAuthKeys.TOKENS.value: {
                "access_token": "current-token",
                "token_type": "Bearer",
            },
        },
    )

    asyncio.run(provider.context.storage.get_tokens())

    assert provider.context.oauth_metadata is not None
    assert (
        str(provider.context.oauth_metadata.token_endpoint)
        == "https://accounts.example.com/token"
    )


def test_token_write_persists_discovered_metadata(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    provider = _provider(MCPOAuthProviderMode.AUTO_DISCOVERY)
    provider.context.oauth_metadata = _DISCOVERED_METADATA
    config_data: dict[str, Any] = {}
    _patch_config_read(monkeypatch, config_data)
    monkeypatch.setattr(oauth, "update_connection_config", MagicMock())

    asyncio.run(
        provider.context.storage.set_tokens(
            OAuthToken(
                access_token="current-token",
                token_type="Bearer",
                expires_in=3600,
            )
        )
    )

    assert config_data[MCPOAuthKeys.METADATA.value] == (
        _DISCOVERED_METADATA.model_dump(mode="json")
    )

"use client";

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { Formik, Form, FormikHelpers } from "formik";
import * as Yup from "yup";
import { Modal } from "@opal/components";
import {
  Button,
  Divider,
  MessageCard,
  InputPasswordTypeIn,
} from "@opal/components";
import InputSelect from "@/refresh-components/inputs/InputSelect";
import { InputTypeIn } from "@opal/components";
import { FormField } from "@/refresh-components/form/FormField";
import Text from "@/refresh-components/texts/Text";
import { CopyButton } from "@opal/components";
import {
  InputKeyValue as KeyValueInput,
  type KeyValue,
} from "@opal/components";
import { OAuthConfig } from "@/lib/tools/types";
import { getOAuthConfig } from "@/lib/oauth/api";
import { SvgArrowExchange } from "@opal/icons";
import { useOAuthPassThroughEnabled } from "@/lib/auth/hooks";

export type AuthMethod = "oauth" | "custom-header" | "pt-oauth";

export interface OpenAPIAuthFormValues {
  authMethod: AuthMethod;
  authorizationUrl: string;
  tokenUrl: string;
  clientId: string;
  clientSecret: string;
  scopes: string;
  headers: KeyValue[];
}

interface OpenAPIAuthenticationModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  description?: string;
  skipOverlay?: boolean;
  defaultMethod?: AuthMethod;
  oauthConfigId?: number | null;
  initialHeaders?: KeyValue[] | null;
  onConnect?: (values: OpenAPIAuthFormValues) => Promise<void> | void;
  onSkip?: () => void;
  entityName?: string | null;
  passthroughOAuthEnabled?: boolean;
}

const MASKED_CREDENTIAL_VALUE = "********";

const defaultValues: OpenAPIAuthFormValues = {
  authMethod: "oauth",
  authorizationUrl: "",
  tokenUrl: "",
  clientId: "",
  clientSecret: "",
  scopes: "",
  headers: [
    {
      key: "Authorization",
      value: "",
    },
  ],
};

export default function OpenAPIAuthenticationModal({
  isOpen,
  onClose,
  title,
  description,
  skipOverlay = false,
  defaultMethod = "oauth",
  oauthConfigId = null,
  initialHeaders = null,
  passthroughOAuthEnabled = false,
  onConnect,
  onSkip,
  entityName = null,
}: OpenAPIAuthenticationModalProps) {
  const t = useTranslations("actions");
  const isOAuthEnabled = useOAuthPassThroughEnabled();
  const [existingOAuthConfig, setExistingOAuthConfig] =
    useState<OAuthConfig | null>(null);
  const [isLoadingOAuthConfig, setIsLoadingOAuthConfig] = useState(false);
  const [oauthConfigError, setOAuthConfigError] = useState<string | null>(null);

  const isEditingOAuthConfig = Boolean(oauthConfigId);
  const hasInitialHeaders =
    Array.isArray(initialHeaders) && initialHeaders.length > 0;
  const isEditMode = isEditingOAuthConfig || hasInitialHeaders;
  const shouldDisableForm =
    isEditingOAuthConfig &&
    isLoadingOAuthConfig &&
    !existingOAuthConfig &&
    !oauthConfigError;

  const redirectUri = useMemo(() => {
    if (typeof window === "undefined") {
      return "https://{YOUR_DOMAIN}/oauth-config/callback";
    }
    return `${window.location.origin}/oauth-config/callback`;
  }, []);

  useEffect(() => {
    let isActive = true;

    if (!isOpen || !oauthConfigId) {
      setExistingOAuthConfig(null);
      setOAuthConfigError(null);
      setIsLoadingOAuthConfig(false);
      return () => {
        isActive = false;
      };
    }

    const fetchConfig = async () => {
      setIsLoadingOAuthConfig(true);
      setOAuthConfigError(null);
      try {
        const config = await getOAuthConfig(oauthConfigId);
        if (!isActive) {
          return;
        }
        setExistingOAuthConfig(config);
      } catch (error) {
        console.error("Failed to load OAuth configuration", error);
        if (isActive) {
          setExistingOAuthConfig(null);
          setOAuthConfigError(t("openApiAuthModal.errors.loadConfigFailed"));
        }
      } finally {
        if (isActive) {
          setIsLoadingOAuthConfig(false);
        }
      }
    };

    fetchConfig();

    return () => {
      isActive = false;
    };
  }, [isOpen, oauthConfigId, t]);

  const dynamicValidationSchema = useMemo(
    () =>
      Yup.object({
        authMethod: Yup.mixed<AuthMethod>()
          .oneOf(["oauth", "pt-oauth", "custom-header"])
          .required(t("openApiAuthModal.authMethod.required")),
        authorizationUrl: Yup.string()
          .url(t("openApiAuthModal.errors.invalidUrl"))
          .when("authMethod", {
            is: "oauth",
            then: (schema) =>
              schema.required(t("openApiAuthModal.authorizationUrl.required")),
            otherwise: (schema) => schema.notRequired(),
          }),
        tokenUrl: Yup.string()
          .url(t("openApiAuthModal.errors.invalidUrl"))
          .when("authMethod", {
            is: "oauth",
            then: (schema) =>
              schema.required(t("openApiAuthModal.tokenUrl.required")),
            otherwise: (schema) => schema.notRequired(),
          }),
        clientId: Yup.string().when("authMethod", {
          is: "oauth",
          then: (schema) =>
            isEditingOAuthConfig
              ? schema.optional()
              : schema.required(t("openApiAuthModal.clientId.required")),
          otherwise: (schema) => schema.notRequired(),
        }),
        clientSecret: Yup.string().when("authMethod", {
          is: "oauth",
          then: (schema) =>
            isEditingOAuthConfig
              ? schema.optional()
              : schema.required(t("openApiAuthModal.clientSecret.required")),
          otherwise: (schema) => schema.notRequired(),
        }),
        scopes: Yup.string().notRequired(),
        headers: Yup.array().when("authMethod", {
          is: "custom-header",
          then: () =>
            Yup.array()
              .of(
                Yup.object({
                  key: Yup.string().required(
                    t("openApiAuthModal.headers.keyRequired")
                  ),
                  value: Yup.string().required(
                    t("openApiAuthModal.headers.valueRequired")
                  ),
                })
              )
              .min(1, t("openApiAuthModal.headers.minRequired")),
          otherwise: () =>
            Yup.array().of(
              Yup.object({
                key: Yup.string(),
                value: Yup.string(),
              })
            ),
        }),
      }),
    [isEditingOAuthConfig, t]
  );

  const computedInitialValues = useMemo<OpenAPIAuthFormValues>(() => {
    const baseHeaders =
      hasInitialHeaders && initialHeaders
        ? initialHeaders.map((header) => ({ ...header }))
        : defaultValues.headers.map((header) => ({ ...header }));

    if (isEditingOAuthConfig) {
      const shouldMaskCredentials = Boolean(
        existingOAuthConfig?.has_client_credentials
      );
      return {
        authMethod: "oauth",
        authorizationUrl:
          existingOAuthConfig?.authorization_url ||
          defaultValues.authorizationUrl,
        tokenUrl: existingOAuthConfig?.token_url || defaultValues.tokenUrl,
        clientId: shouldMaskCredentials ? MASKED_CREDENTIAL_VALUE : "",
        clientSecret: shouldMaskCredentials ? MASKED_CREDENTIAL_VALUE : "",
        scopes: existingOAuthConfig?.scopes?.join(", ") || "",
        headers: baseHeaders,
      };
    }

    if (hasInitialHeaders && initialHeaders) {
      return {
        ...defaultValues,
        authMethod: "custom-header",
        headers: baseHeaders,
      };
    }

    if (passthroughOAuthEnabled) {
      return {
        ...defaultValues,
        authMethod: "pt-oauth",
      };
    }

    return {
      ...defaultValues,
      authMethod: defaultMethod,
      headers: baseHeaders,
    };
  }, [
    defaultMethod,
    existingOAuthConfig,
    hasInitialHeaders,
    initialHeaders,
    isEditingOAuthConfig,
    passthroughOAuthEnabled,
  ]);

  const handleSubmit = useCallback(
    async (
      values: OpenAPIAuthFormValues,
      formikHelpers: FormikHelpers<OpenAPIAuthFormValues>
    ) => {
      if (shouldDisableForm) {
        formikHelpers.setSubmitting(false);
        return;
      }
      const sanitizeCredentials = (
        formValues: OpenAPIAuthFormValues
      ): OpenAPIAuthFormValues => {
        if (!isEditingOAuthConfig || formValues.authMethod !== "oauth") {
          return formValues;
        }

        const sanitizeValue = (value: string) =>
          value === MASKED_CREDENTIAL_VALUE ? "" : value;

        return {
          ...formValues,
          clientId: sanitizeValue(formValues.clientId),
          clientSecret: sanitizeValue(formValues.clientSecret),
        };
      };

      try {
        const sanitizedValues = sanitizeCredentials(values);
        await onConnect?.(sanitizedValues);
        onClose();
      } finally {
        formikHelpers.setSubmitting(false);
      }
    },
    [onConnect, onClose, shouldDisableForm]
  );

  const handleSkip = useCallback(() => {
    if (onSkip) {
      onSkip();
    } else {
      onClose();
    }
  }, [onSkip, onClose]);

  return (
    <Modal
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) {
          onClose();
        }
      }}
    >
      <Modal.Content width="sm" height="lg" skipOverlay={skipOverlay}>
        <Modal.Header
          icon={SvgArrowExchange}
          title={title}
          description={description ?? t("openApiAuthModal.header.description")}
          onClose={onClose}
        />

        <Formik
          initialValues={computedInitialValues}
          validationSchema={dynamicValidationSchema}
          validateOnMount
          enableReinitialize
          onSubmit={handleSubmit}
        >
          {({
            values,
            errors,
            touched,
            handleChange,
            setFieldValue,
            setFieldError,
            isSubmitting,
            isValid,
            dirty,
          }) => (
            <Form className="flex flex-col h-full">
              <Modal.Body>
                {oauthConfigError && (
                  <div className="mb-3">
                    <Text
                      as="p"
                      mainUiBody
                      className="text-action-text-danger-05"
                    >
                      {oauthConfigError}
                    </Text>
                  </div>
                )}

                {shouldDisableForm ? (
                  <div className="flex min-h-[220px] items-center justify-center rounded-12 border border-border-01 bg-background-tint-00">
                    <Text as="p" secondaryBody text03>
                      {t("openApiAuthModal.loading.label")}
                    </Text>
                  </div>
                ) : (
                  <>
                    <div className="flex flex-col gap-4 px-2 pt-2">
                      <FormField
                        name="authMethod"
                        state={
                          errors.authMethod && touched.authMethod
                            ? "error"
                            : touched.authMethod
                              ? "success"
                              : "idle"
                        }
                      >
                        <FormField.Label>
                          {t("openApiAuthModal.authMethod.label")}
                        </FormField.Label>
                        <FormField.Control asChild>
                          <InputSelect
                            value={values.authMethod}
                            onValueChange={(value) =>
                              setFieldValue("authMethod", value)
                            }
                          >
                            <InputSelect.Trigger
                              placeholder={t(
                                "openApiAuthModal.authMethod.placeholder"
                              )}
                            />
                            <InputSelect.Content>
                              <InputSelect.Item
                                value="oauth"
                                description={t(
                                  "openApiAuthModal.authMethod.oauth.description"
                                )}
                              >
                                {t("openApiAuthModal.authMethod.oauth.label")}
                              </InputSelect.Item>
                              {isOAuthEnabled && (
                                <InputSelect.Item
                                  value="pt-oauth"
                                  description={t(
                                    "openApiAuthModal.authMethod.ptOauth.description"
                                  )}
                                >
                                  {t(
                                    "openApiAuthModal.authMethod.ptOauth.label"
                                  )}
                                </InputSelect.Item>
                              )}
                              <InputSelect.Item
                                value="custom-header"
                                description={t(
                                  "openApiAuthModal.authMethod.customHeader.description"
                                )}
                              >
                                {t(
                                  "openApiAuthModal.authMethod.customHeader.label"
                                )}
                              </InputSelect.Item>
                            </InputSelect.Content>
                          </InputSelect>
                        </FormField.Control>
                        <FormField.Message
                          messages={{
                            error: errors.authMethod,
                          }}
                        />
                      </FormField>
                    </div>

                    <Divider paddingPerpendicular={0} />

                    {values.authMethod === "oauth" && (
                      <section className="flex flex-col gap-4 rounded-12 bg-background-tint-00 border border-border-01 p-4">
                        <FormField
                          name="authorizationUrl"
                          state={
                            errors.authorizationUrl && touched.authorizationUrl
                              ? "error"
                              : touched.authorizationUrl
                                ? "success"
                                : "idle"
                          }
                        >
                          <FormField.Label>
                            {t("openApiAuthModal.authorizationUrl.label")}
                          </FormField.Label>
                          <FormField.Control asChild>
                            <InputTypeIn
                              name="authorizationUrl"
                              value={values.authorizationUrl}
                              onChange={handleChange}
                              placeholder="https://example.com/oauth/authorize"
                            />
                          </FormField.Control>
                          <FormField.Message
                            messages={{
                              error: errors.authorizationUrl,
                            }}
                          />
                        </FormField>

                        <FormField
                          name="tokenUrl"
                          state={
                            errors.tokenUrl && touched.tokenUrl
                              ? "error"
                              : touched.tokenUrl
                                ? "success"
                                : "idle"
                          }
                        >
                          <FormField.Label>
                            {t("openApiAuthModal.tokenUrl.label")}
                          </FormField.Label>
                          <FormField.Control asChild>
                            <InputTypeIn
                              name="tokenUrl"
                              value={values.tokenUrl}
                              onChange={handleChange}
                              placeholder="https://example.com/oauth/access_token"
                            />
                          </FormField.Control>
                          <FormField.Message
                            messages={{
                              error: errors.tokenUrl,
                            }}
                          />
                        </FormField>

                        <FormField
                          name="clientId"
                          state={
                            errors.clientId && touched.clientId
                              ? "error"
                              : touched.clientId
                                ? "success"
                                : "idle"
                          }
                        >
                          <FormField.Label>
                            {t("openApiAuthModal.clientId.label")}
                          </FormField.Label>
                          <FormField.Control asChild>
                            <InputTypeIn
                              name="clientId"
                              value={values.clientId}
                              onChange={handleChange}
                              placeholder=" "
                            />
                          </FormField.Control>
                          {isEditingOAuthConfig && (
                            <FormField.Description>
                              {t("openApiAuthModal.clientId.description")}
                            </FormField.Description>
                          )}
                          <FormField.Message
                            messages={{
                              error: errors.clientId,
                            }}
                          />
                        </FormField>

                        <FormField
                          name="clientSecret"
                          state={
                            errors.clientSecret && touched.clientSecret
                              ? "error"
                              : touched.clientSecret
                                ? "success"
                                : "idle"
                          }
                        >
                          <FormField.Label>
                            {t("openApiAuthModal.clientSecret.label")}
                          </FormField.Label>
                          <FormField.Control asChild>
                            <InputPasswordTypeIn
                              name="clientSecret"
                              value={values.clientSecret}
                              onChange={handleChange}
                              placeholder=" "
                            />
                          </FormField.Control>
                          {isEditingOAuthConfig && (
                            <FormField.Description>
                              {t("openApiAuthModal.clientSecret.description")}
                            </FormField.Description>
                          )}
                          <FormField.Message
                            messages={{
                              error: errors.clientSecret,
                            }}
                          />
                        </FormField>

                        <FormField
                          name="scopes"
                          state={
                            errors.scopes && touched.scopes
                              ? "error"
                              : touched.scopes
                                ? "success"
                                : "idle"
                          }
                        >
                          <FormField.Label>
                            {t.rich("openApiAuthModal.scopes.label", {
                              optional: (chunks) => (
                                <span className="text-text-03">{chunks}</span>
                              ),
                            })}
                          </FormField.Label>
                          <FormField.Control asChild>
                            <InputTypeIn
                              name="scopes"
                              value={values.scopes}
                              onChange={handleChange}
                              placeholder={t(
                                "openApiAuthModal.scopes.placeholder"
                              )}
                            />
                          </FormField.Control>
                          <FormField.Description>
                            {t("openApiAuthModal.scopes.description")}
                          </FormField.Description>
                          <FormField.Message
                            messages={{
                              error: errors.scopes,
                            }}
                          />
                        </FormField>

                        <div className="flex flex-col gap-3 rounded-12 bg-background-tint-01 p-3">
                          <Text as="p" text03 secondaryBody>
                            {t("openApiAuthModal.oauthLoginNotice.description")}
                          </Text>
                          <div className="flex flex-col gap-2 w-full">
                            <Text
                              as="p"
                              text03
                              secondaryBody
                              className="flex flex-wrap gap-1"
                            >
                              {t.rich("openApiAuthModal.redirectUri.label", {
                                emphasis: (chunks) => (
                                  <span className="font-secondary-action">
                                    {chunks}
                                  </span>
                                ),
                              })}
                            </Text>
                            <div className="flex items-center gap-2 rounded-08 border border-border-01 bg-background-tint-00 px-3 py-2">
                              <Text
                                as="p"
                                text04
                                className="font-mono text-[12px] leading-[16px] truncate flex-1"
                              >
                                {redirectUri}
                              </Text>
                              <CopyButton
                                getCopyText={() => redirectUri}
                                tooltip={t(
                                  "openApiAuthModal.redirectUri.copyTooltip"
                                )}
                                prominence="tertiary"
                                size="sm"
                              />
                            </div>
                          </div>
                        </div>
                      </section>
                    )}
                    {values.authMethod === "custom-header" && (
                      <section className="flex flex-col gap-4 rounded-12 bg-background-tint-00 border border-border-01 p-4">
                        <div className="flex flex-col gap-2">
                          <Text as="p" mainUiAction text04>
                            {t("openApiAuthModal.headers.title")}
                          </Text>
                          <Text as="p" secondaryBody text03>
                            {t("openApiAuthModal.headers.description")}
                          </Text>
                        </div>
                        <FormField
                          name="headers"
                          state={errors.headers ? "error" : "idle"}
                        >
                          <FormField.Control asChild>
                            <KeyValueInput
                              keyTitle={t("openApiAuthModal.headers.keyTitle")}
                              valueTitle={t(
                                "openApiAuthModal.headers.valueTitle"
                              )}
                              items={values.headers}
                              onChange={(items) =>
                                setFieldValue("headers", items)
                              }
                              addButtonLabel={t(
                                "openApiAuthModal.headers.addButton.label"
                              )}
                              onValidationError={(message) =>
                                setFieldError("headers", message || undefined)
                              }
                              layout="equal"
                            />
                          </FormField.Control>
                          <FormField.Message
                            messages={{
                              error:
                                typeof errors.headers === "string"
                                  ? errors.headers
                                  : undefined,
                            }}
                          />
                        </FormField>
                      </section>
                    )}
                    {values.authMethod === "pt-oauth" && (
                      <MessageCard
                        title={t("openApiAuthModal.passThroughNotice.title")}
                        description={t(
                          "openApiAuthModal.passThroughNotice.description"
                        )}
                      />
                    )}
                  </>
                )}
              </Modal.Body>

              <Modal.Footer>
                <Button
                  prominence="tertiary"
                  type="button"
                  onClick={handleSkip}
                >
                  {t("openApiAuthModal.cancelButton.label")}
                </Button>
                <Button
                  disabled={
                    !isValid || isSubmitting || shouldDisableForm || !dirty
                  }
                  type="submit"
                >
                  {isSubmitting
                    ? t("openApiAuthModal.submitButton.pendingLabel")
                    : t("openApiAuthModal.submitButton.label")}
                </Button>
              </Modal.Footer>
            </Form>
          )}
        </Formik>
      </Modal.Content>
    </Modal>
  );
}

"use client";

